import React, { useState } from "react";
import AchievementsPanel from "./AchievementsPanel";
import UserProfileCard from './UserProfileCard'; // Assuming this component has styling

export default function AdminDashboard({ reports, token, setMsg, admin }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [mostActive, setMostActive] = useState(null);

  const API = process.env.REACT_APP_API || "http://localhost:4000";

  // --- THEME COLORS & STYLES ---
  const PRIMARY_COLOR = "#007bff"; // Vibrant Blue for actions/highlights
  const ACCENT_COLOR = "#28a745"; // Success Green
  const LIGHT_BG = "#f8f9fa"; // Light background for the dashboard body
  const CARD_BG = "#ffffff";
  const ERROR_COLOR = "#dc3545"; // Red for removals
  const BORDER_RADIUS = 10;
  // -------------------------------

  // Clears all sections
  const clearAll = () => {
    setNgos(null);
    setEvents(null);
    setEventStats(null);
    setMostActive(null);
  };

  const loadData = async (endpoint, setter, expectedField = null, errMsg = "Failed to load") => {
    if (!token) return setMsg("Login as admin first");

    clearAll();

    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || errMsg);
        } catch {
          throw new Error(errMsg);
        }
      }

      const data = await res.json();

      // If expectedField is provided and exists on response, use it
      if (expectedField && (data[expectedField] !== undefined && data[expectedField] !== null)) {
        setter(data[expectedField]);
        return;
      }

      // Flexible fallbacks for common shapes from your backend
      const fallbackCandidates = [
        "top",
        "mostActive",
        "most",
        "badges",
        "ngos",
        "events",
        "volunteers",
        "donors",
        "results",
        "participants",
        "donations",
        "user_badges",
      ];

      for (const key of fallbackCandidates) {
        if (data[key] !== undefined && data[key] !== null) {
          setter(data[key]);
          return;
        }
      }

      // If server returned an array directly or object, pass it through
      setter(data);
    } catch (err) {
      console.error(err);
      setMsg(err.message || errMsg);
    }
  };

  // Most Active NGO fetch
  const loadMostActive = async () => {
    if (!token) return setMsg("Login as admin first");

    clearAll();

    try {
      const res = await fetch(`${API}/api/actions/most-active-ngo`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || "Failed to load most active NGO");
        } catch {
          throw new Error("Failed to load most active NGO");
        }
      }

      const data = await res.json();

      const candidate = data.mostActive || data.most || data.top || data.most_active || data[0] || null;

      if (Array.isArray(candidate)) {
        setMostActive(candidate[0] || null);
      } else {
        setMostActive(candidate || null);
      }
    } catch (err) {
      console.error(err);
      setMsg(err.message || "Failed to load most active NGO");
    }
  };

  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");
    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || "Failed to delete NGO");
        } catch {
          throw new Error("Failed to delete NGO");
        }
      }

      setMsg("NGO removed successfully");
      setNgos((prev) => (Array.isArray(prev) ? prev.filter((n) => n.id !== id) : prev));
    } catch (err) {
      console.error(err);
      setMsg(err.message);
    }
  };

  // Helper render for results (eventStats, top lists, badges)
  const renderResults = (results) => {
    if (!results) return null;

    const list = Array.isArray(results) ? results : [results];

    if (!list.length) return <p style={{ color: "#6c757d" }}>No data found.</p>;

    return list.map((item, i) => {
      const baseStyle = {
        padding: 12,
        background: CARD_BG,
        borderRadius: BORDER_RADIUS,
        marginBottom: 10,
        boxShadow: "0 2px 5px rgba(0,0,0,0.05)",
      };

      // Event-like item
      if (item.title || item.event_title) {
        const title = item.title || item.event_title;
        const date = item.date || item.created_at || item.event_date;
        return (
          <div key={item.id || i} style={baseStyle}>
            <strong>{title}</strong>
            {date && <div style={{ fontSize: 13, color: "#6c757d" }}>🗓️ {date}</div>}
            {item.volunteers_count !== undefined && (
              <div style={{ fontSize: 13 }}>👥 Volunteers: {item.volunteers_count}</div>
            )}
            {item.donations_sum !== undefined && (
              <div style={{ fontSize: 13 }}>💰 Donations: ₹{item.donations_sum}</div>
            )}
          </div>
        );
      }

      // Volunteer / Donor / User-like item
      if (item.name || item.user_name || item.donor_name || item.email) {
        const name = item.name || item.user_name || item.donor_name || item.email;
        return (
          <div
            key={item.id || i}
            style={{
              ...baseStyle,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <div>
              <strong>{name}</strong>
              {item.email && <div style={{ fontSize: 13, color: "#6c757d" }}>{item.email}</div>}
              {item.amount !== undefined && <div style={{ fontSize: 13 }}>💲 Amount: ₹{item.amount}</div>}
              {item.points !== undefined && <div style={{ fontSize: 13 }}>✨ Points: {item.points}</div>}
            </div>
            {/* small meta */}
            <div style={{ fontSize: 12, color: "#999", textAlign: "right" }}>
              {item.created_at && <div>{new Date(item.created_at).toLocaleString()}</div>}
            </div>
            
          </div>
        );
      }

      // Badge-like item
      if (item.title && item.description) {
        return (
          <div key={item.key || i} style={baseStyle}>
            <strong>🎖️ {item.title}</strong>
            <div style={{ fontSize: 13, color: "#6c757d" }}>{item.description || item.desc}</div>
            {item.key && <div style={{ fontSize: 12, color: "#999" }}>Key: {item.key}</div>}
          </div>
        );
      }

      // Fallback generic display of object
      return (
        <div key={i} style={baseStyle}>
          <pre style={{ margin: 0, whiteSpace: "pre-wrap", fontSize: 12 }}>
            {JSON.stringify(item, null, 2)}
          </pre>
        </div>
      );
    });
  };

  // Unified button style
  const buttonStyle = {
    background: PRIMARY_COLOR,
    color: CARD_BG,
    border: "none",
    padding: "10px 15px",
    borderRadius: BORDER_RADIUS,
    cursor: "pointer",
    transition: "background-color 0.2s, transform 0.1s",
    fontWeight: 600,
    fontSize: 14,
  };
  
  // Secondary button style for actions that fetch data
  const secondaryButtonStyle = {
    background: LIGHT_BG,
    color: PRIMARY_COLOR,
    border: `1px solid ${PRIMARY_COLOR}`,
    padding: "8px 12px",
    borderRadius: BORDER_RADIUS,
    cursor: "pointer",
    transition: "background-color 0.2s",
    fontSize: 14,
    fontWeight: 500,
  };


  return (
    <div style={{ background: LIGHT_BG, minHeight: "100vh", padding: 20 }}>
      <h2>Admin Dashboard 📊</h2>
      <div style={{ display: "flex", gap: 20, alignItems: "flex-start", marginTop: 20 }}>
        {/* LEFT PANEL - Main Content Area */}
        <div style={{ flex: 1 }}>

          {/* ⭐ ADMIN PROFILE HEADER ⭐ */}
          <div
            style={{
              background: CARD_BG,
              padding: "16px",
              borderRadius: BORDER_RADIUS,
              marginBottom: 20,
              boxShadow: "0 6px 20px rgba(0,0,0,0.08)",
              display: "flex",
              alignItems: "center",
              gap: 16,
            }}
          >
            <div
              style={{
                width: 48,
                height: 48,
                borderRadius: "50%",
                background: PRIMARY_COLOR,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                fontSize: 24,
                fontWeight: 700,
                color: CARD_BG,
              }}
            >
              A
            </div>

            <div>
              <div style={{ fontWeight: 700, fontSize: 18 }}>
                Admin User: {admin?.email || "admin@ngo.local"}
              </div>
              <div style={{ fontSize: 14, color: "#6c757d" }}>Super Administrator</div>
            </div>
          </div>

          <div style={{ marginBottom: 20 }}>
            <AchievementsPanel
              token={token}
              me={{ points: reports?.adminPoints || 0 }}
              role="user"
              setMsg={setMsg}
            />
          </div>
          
          <hr style={{ borderTop: "1px solid #dee2e6", margin: "20px 0" }} />


          <h3>📈 System Reports</h3>

          {/* STATS CARDS */}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
              gap: 16,
              marginBottom: 20,
            }}
          >
            <div
              style={{
                background: CARD_BG,
                padding: 20,
                borderRadius: BORDER_RADIUS,
                boxShadow: "0 2px 10px rgba(0,0,0,0.05)",
              }}
            >
              <div style={{ fontSize: 32, fontWeight: 700, color: ACCENT_COLOR }}>
                ₹
                {reports?.donations
                  ? reports.donations.reduce(
                      (sum, d) => sum + parseFloat(d.amount || 0),
                      0
                    ).toLocaleString()
                  : "-"}
              </div>
              <div style={{ fontSize: 14, color: "#6c757d", marginTop: 4 }}>Total Donations</div>
            </div>

            <div
              style={{
                background: CARD_BG,
                padding: 20,
                borderRadius: BORDER_RADIUS,
                boxShadow: "0 2px 10px rgba(0,0,0,0.05)",
              }}
            >
              <div style={{ fontSize: 32, fontWeight: 700, color: PRIMARY_COLOR }}>
                {reports?.volunteers?.length || 0}
              </div>
              <div style={{ fontSize: 14, color: "#6c757d", marginTop: 4 }}>Total Volunteers</div>
            </div>

            <div
              style={{
                background: CARD_BG,
                padding: 20,
                borderRadius: BORDER_RADIUS,
                boxShadow: "0 2px 10px rgba(0,0,0,0.05)",
              }}
            >
              <div style={{ fontSize: 32, fontWeight: 700, color: "#ffc107" }}>
                {reports?.feedbacks?.length || 0}
              </div>
              <div style={{ fontSize: 14, color: "#6c757d", marginTop: 4 }}>New Feedbacks</div>
            </div>
          </div>

          {/* DATA VIEW BUTTONS */}
          <div style={{ marginTop: 12, display: "flex", flexWrap: "wrap", gap: 10 }}>
            <button
              onClick={() =>
                loadData("/api/actions/ngos", setNgos, "ngos", "Failed to load NGOs")
              }
              style={secondaryButtonStyle}
            >
              View Registered NGOs
            </button>

            <button
              onClick={() =>
                loadData(
                  "/api/actions/registered-events",
                  setEvents,
                  "events",
                  "Failed to load events"
                )
              }
              style={secondaryButtonStyle}
            >
              View Registered Events
            </button>

            <button
              onClick={() =>
                loadData(
                  "/api/actions/event-stats",
                  setEventStats,
                  "events",
                  "Failed to load event stats"
                )
              }
              style={secondaryButtonStyle}
            >
              View Event Stats
            </button>
          </div>

          <hr style={{ borderTop: "1px solid #dee2e6", margin: "20px 0" }} />

          {/* DYNAMIC CONTENT DISPLAY */}
          {events && (
            <div style={{ marginTop: 20 }}>
              <h4>Registered Events 📅</h4>
              {Array.isArray(events) && events.length ? (
                events.map((e) => (
                  <div
                    key={e.id}
                    style={{
                      padding: 12,
                      background: CARD_BG,
                      borderRadius: BORDER_RADIUS,
                      marginBottom: 10,
                      boxShadow: "0 2px 5px rgba(0,0,0,0.05)",
                    }}
                  >
                    <strong>{e.title}</strong>
                    <div style={{ fontSize: 13, color: "#6c757d" }}>{e.date || e.created_at}</div>
                  </div>
                ))
              ) : (
                <p style={{ color: "#6c757d" }}>No events registered.</p>
              )}
            </div>
          )}

          {eventStats && (
            <div style={{ marginTop: 20 }}>
              <h4>Query Results 📋</h4>
              {renderResults(eventStats)}
            </div>
          )}

          {ngos && (
            <div style={{ marginTop: 20 }}>
              <h4>Registered NGOs 🏢</h4>
              {Array.isArray(ngos) && ngos.length ? (
                ngos.map((n) => (
                  <div
                    key={n.id}
                    style={{
                      padding: 12,
                      background: CARD_BG,
                      borderRadius: BORDER_RADIUS,
                      marginBottom: 10,
                      boxShadow: "0 2px 5px rgba(0,0,0,0.05)",
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                    }}
                  >
                    <div>
                      <strong>{n.name}</strong>
                      <div style={{ fontSize: 13, color: "#6c757d" }}>{n.email}</div>
                    </div>

                    <button
                      style={{
                        padding: "6px 12px",
                        background: ERROR_COLOR,
                        color: CARD_BG,
                        border: "none",
                        borderRadius: 6,
                        cursor: "pointer",
                        fontSize: 13,
                      }}
                      onClick={() => deleteNgo(n.id)}
                    >
                      Remove
                    </button>
                  </div>
                ))
              ) : (
                <p style={{ color: "#6c757d" }}>No NGOs registered.</p>
              )}
            </div>
          )}
        </div>

        {/* RIGHT PANEL - Sticky Sidebar */}
        <div
          style={{
            width: 280,
            flexShrink: 0,
            position: "sticky",
            top: 20, 
            display: "flex",
            flexDirection: "column",
            gap: 20,
          }}
        >
          {/* Quick Actions */}
          <div
            style={{
              background: CARD_BG,
              padding: 16,
              borderRadius: BORDER_RADIUS,
              border: `2px solid ${PRIMARY_COLOR}`, // Highlight border
              boxShadow: "0 6px 20px rgba(0,0,0,0.08)",
            }}
          >
            <h4>⚡ Quick Actions</h4>

            <button
              onClick={() =>
                loadData(
                  "/api/actions/top-volunteers",
                  setEventStats,
                  "top",
                  "Failed to load top volunteers"
                )
              }
              style={{ ...buttonStyle, width: "100%", marginTop: 10, marginBottom: 8 }}
            >
              Top Volunteers
            </button>

            <button
              onClick={() =>
                loadData(
                  "/api/actions/top-donors",
                  setEventStats,
                  "top",
                  "Failed to load top donors"
                )
              }
              style={{ ...buttonStyle, width: "100%", marginBottom: 8 }}
            >
              Top Donors
            </button>

            <button
              onClick={() =>
                loadData(
                  "/api/actions/badges",
                  setEventStats,
                  "badges",
                  "Failed to load badges"
                )
              }
              style={{ ...buttonStyle, width: "100%" }}
            >
              View Badges
            </button>
          </div>

          {/* Most Active NGO */}
          <div
            style={{
              background: CARD_BG,
              padding: 16,
              borderRadius: BORDER_RADIUS,
              border: "1px solid #dee2e6",
              boxShadow: "0 2px 5px rgba(0,0,0,0.05)",
            }}
          >
            <h4>🏆 Most Active NGO</h4>

            <button
              onClick={loadMostActive}
              style={{ ...secondaryButtonStyle, width: "100%", marginTop: 8 }}
            >
              Load Most Active NGO
            </button>

            {mostActive && (
              <div style={{ marginTop: 12, padding: 10, background: LIGHT_BG, borderRadius: 6 }}>
                <strong>{mostActive.name}</strong>
                <div style={{ fontSize: 13, color: PRIMARY_COLOR, fontWeight: 600 }}>
                  Activity Score: {(mostActive?.activity_score ?? mostActive?.activityScore ?? mostActive?.activity) ?? "N/A"}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
